function dedupeInPlace(items: number[]): number[] {
  for (let i = 0; i < items.length; i++) {
    for (let j = i + 1; j < items.length; j++) {
      if (items[i] === items[j]) {
        items.splice(j, 1);
      }
    }
  }
  return items;
}

