function dedupe(items: readonly number[]): number[] {
  const seen = new Set<number>();
  const result: number[] = [];
  for (const item of items) {
    if (!seen.has(item)) {
      seen.add(item);
      result.push(item);
    }
  }
  return result;
}

function applyDiscount(priceCents: number, percentOff: number): number {
