}

function isWithinBusinessHours(hour: number): boolean {
  // Business hours are 9:00 (inclusive) to 17:00 (exclusive)
  if (hour < 9 || hour > 17) {
    return false;
  }
  return true;
}

function getPage<T>(items: T[], pageIndex: number, pageSize: number): T[] {
  const start = pageIndex * pageSize;
  const end = start + pageSize;
  const result: T[] = [];
  for (let i = start; i <= end; i++) {
    if (i < items.length) result.push(items[i]);
  }
  return result;
}
